…
      return;
    }
    setState(() {
      _inviteValidating = true;
      _inviteError = null;
    });
    try {
      final dio = ref.read(dioClientProvider);
      await dio.dio.post(
        '/tournaments/${widget.tournamentId}/validate-invite',
        data: {'inviteCode': code},
      );
      if (mounted) setState(() => _localInviteCode = code);
    } catch (e) {
      if (mounted) {
        setState(() => _inviteError = l10n.registerInviteInvalid);
      }
    } finally {
      if (mounted) setState(() => _inviteValidating = false);
    }
  }

  Future<void> _register() async {
    if (_alreadyRegistered) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text(l10n.registerAlreadyRegistered)));
      return;
    }
    if (!_formKey.currentState!.validate()) return;
    final userAsync = ref.read(userProfileProvider);
    final user = userAsync.asData?.value;
    final missingFields = <String>[];
    if (user?.fullName == null || user!.fullName!.trim().isEmpty) {
      missingFields.add(l10n.registerMissingFullName);
    }
    if (user?.phoneNumber == null || user!.phoneNumber!.trim().isEmpty) {
      missingFields.add(l10n.registerMissingPhone);
    }
    if (user?.gender == null || user!.gender!.trim().isEmpty) {
      missingFields.add(l10n.registerMissingGender);
    }

    if (missingFields.isNotEmpty) {
      if (mounted) {
        final missingStr = missingFields.join(', ');
        showDialog(
          context: context,
          builder: (ctx) => AlertDialog(
            title: Text(l10n.registerProfileIncompleteTitle),
            content: Text(l10n.registerProfileIncompleteFields(missingStr)),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(ctx),
                child: Text(l10n.registerClose),
              ),
              ElevatedButton(
                onPressed: () {
                  Navigator.pop(ctx);
                  context.push('/profile');
                },
                child: Text(l10n.registerUpdateProfile),
              ),
            ],
          ),
        );
      }
      return;
    }
    if (_genderError != null) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text(_genderError!)));
      }
      return;
    }
    if (_eloError != null) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text(_eloError!)));
      }
      return;
    }
    final tournament = ref
        .read(tournamentProvider(widget.tournamentId))
        .asData
        ?.value;
    final divisions = ref.read(_divisionsProvider(widget.tournamentId)).value;
    final divisionId =
        _selectedDiv ??
        (divisions != null && divisions.length == 1
            ? divisions.first.id
            : null);
    if (divisions != null && divisions.length > 1 && divisionId == null) {
      setState(() => _divisionError = l10n.registerSelectDivision);
      return;
    }
    if (tournament != null) {
      final customError = _validateCustomResponses(tournament);
      if (customError != null) {
        if (mounted) {
          ScaffoldMessenger.of(
            context,
          ).showSnackBar(SnackBar(content: Text(customError)));
        }

        return;
      }
    }
    // Team sport (bóng đá): config có teamSize → đăng ký đội nhiều người
    final tournamentForTeam = ref
        .read(tournamentProvider(widget.tournamentId))
        .asData
        ?.value;
    if (tournamentForTeam != null &&
        (tournamentForTeam.teamSize != null ||
            tournamentForTeam.minTeamSize != null)) {
      final inviteCode = _localInviteCode ?? widget.inviteCode ?? '';
      final selectedTeamDivision = divisions
          ?.where((d) => d.id == divisionId)
          .firstOrNull;
      final query = <String, String>{
        'invite': inviteCode,
        ...?(divisionId == null ? null : {'divisionId': divisionId}),
        if (selectedTeamDivision?.categoryId != null)
          'categoryId': selectedTeamDivision!.categoryId!,
        if (tournamentForTeam.teamSize != null)
          'teamSize': '${tournamentForTeam.teamSize}',
        if (tournamentForTeam.maxReserve != null)
          'maxReserve': '${tournamentForTeam.maxReserve}',
        if (_rankingConsent) 'rankingConsent': 'true',
      };
      await context.push(
        Uri(
          path: '/register/${widget.tournamentId}/team',
          queryParameters: query,
        ).toString(),
      );
      if (mounted) {
        // The team flow mutates the participant/division counters outside this
        // screen. Refresh them when it returns instead of showing stale data.
        ref.invalidate(tournamentProvider(widget.tournamentId));
        ref.invalidate(tournamentIntroProvider(widget.tournamentId));
        ref.invalidate(_divisionsProvider(widget.tournamentId));
      }
      return;
    }
    // If doubles division, navigate to doubles flow
    final selectedDiv = divisions?.where((d) => d.id == divisionId).firstOrNull;
    if (selectedDiv != null &&
        (_normalizedMatchType(selectedDiv.matchType) == 'DOUBLES' ||
            _normalizedMatchType(selectedDiv.matchType) == 'MIXED_DOUBLES')) {
      final inviteCode = _localInviteCode ?? widget.inviteCode ?? '';
      final query = <String, String>{
        'divisionId': divisionId ?? '',
        'invite': inviteCode,
        if (_rankingConsent) 'rankingConsent': 'true',
      };
      context.push(
        Uri(
          path: '/register/${widget.tournamentId}/doubles',
          queryParameters: query,
        ).toString(),
        extra: selectedDiv,
      );
      return;
    }
    final String effectiveTeamName = _nameCtrl.text.trim().isNotEmpty
        ? _nameCtrl.text.trim()
        : (user?.fullName?.trim().isNotEmpty == true
              ? user!.fullName!.trim()
              : l10n.registerTypeDefault);

    setState(() => _submitting = true);
    try {
      final result = await ref
          .read(tournamentRepositoryProvider)
          .registerParticipant(
            tournamentId: widget.tournamentId,
            teamName: effectiveTeamName,
            divisionId: divisionId,
            inviteCode: _localInviteCode ?? widget.inviteCode,
            rankingConsent: _rankingConsent,
            customResponses: _customResponses,
          );
      if (!mounted) return;
      // Refresh the detail streams so the participant count reflects the
      // successful registration when the user returns to the tournament.
      ref.invalidate(tournamentProvider(widget.tournamentId));
      ref.invalidate(tournamentIntroProvider(widget.tournamentId));
      final t = ref.read(tournamentProvider(widget.tournamentId)).asData?.value;
      final effectiveFee = result.entryFee;
      _registrationTeamStatus = result.teamStatus;
      _registeredDivision = selectedDiv;
      final canProceedToPayment =
          !result.isWaitlisted && result.paymentEligible;

      if (effectiveFee > 0 &&
          result.participantId.isNotEmpty &&
          canProceedToPayment) {
        context.push(
          '/payment/checkout',
          extra: {
            'tournamentId': widget.tournamentId,
            'participantId': result.participantId,
            'divisionId': divisionId,
            'amount': effectiveFee,
            'tournamentName': t?.name ?? l10n.payments_defaultTournamentName,
          },
        );
      } else {
        setState(() {
          _success = true;
          _registeredEntryFee = effectiveFee;
        });
      }
    } catch (e) {
      if (mounted) {
        String msg = ErrorParser.parse(e, l10n.registerError);
