    required this.division,
    this.inviteCode,
    this.rankingConsent,
  });

  @override
  ConsumerState<DoublesRegistrationFlow> createState() =>
      _DoublesRegistrationFlowState();
}

class _DoublesRegistrationFlowState
    extends ConsumerState<DoublesRegistrationFlow> {
  int _step = 1;
