  Widget _buildStepIndicator(AppColorsExtension colors) {
    return Row(
      children: [1, 2, 3].map((i) {
        final active = _step >= i;
        final done = _step > i;
        return Expanded(
          child: Row(
            children: [
              if (i > 1)
                Expanded(
                  child: Container(
                    height: 2,
                    color: done || _step > i ? AppTheme.primary : colors.border,
                  ),
                ),
              Container(
                width: 32,
                height: 32,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: active ? AppTheme.primary : colors.bgCard,
                  border: Border.all(
                    color: active ? AppTheme.primary : colors.border,
                    width: 2,
                  ),
                ),
                child: Center(
                  child: done
                      ? const Icon(Icons.check, size: 18, color: Colors.white)
                      : Text(
                          '$i',
                          style: TextStyle(
                            fontSize: 13,
                            fontWeight: FontWeight.w800,
                            color: active ? Colors.white : colors.textMuted,
                          ),
                        ),
                ),
              ),
              if (i < 3)
                Expanded(
                  child: Container(
                    height: 2,
                    color: done ? AppTheme.primary : colors.border,
                  ),
                ),
            ],
          ),
        );
      }).toList(),
    );
  }

